baseline.sql:
SELECT COUNT(DISTINCT card_id) AS num_release_promo_cards
FROM cards
WHERE promotion_type = 'release';

SELECT COUNT(*) AS total_rulings
FROM rulings
WHERE card_id = (
  SELECT id FROM cards WHERE LOWER(name) = 'fireball' LIMIT 1
);

SELECT COUNT(DISTINCT name) AS card_count
FROM cards
WHERE frame >= '2015' AND text IS NOT NULL AND TRIM(text) != '';

SELECT COUNT(DISTINCT language) AS foreign_language_count
FROM set_translations
WHERE card_name = 'Swamp';

treatment.sql:
SELECT COUNT(DISTINCT language) AS num_foreign_languages
FROM foreign_data
WHERE name = 'Swamp';

SELECT SUM(Reputation) AS total_reputation
FROM users
WHERE Location LIKE '%United Kingdom%'
  AND EXISTS (
    SELECT 1 FROM posts WHERE posts.OwnerUserId = users.Id
  );

SELECT COUNT(DISTINCT link_to_major) AS num_distinct_majors
FROM member
WHERE position = 'Political Science';

SELECT COUNT(*) AS num_characters_no_race
FROM superhero
WHERE publisher_id = (
    SELECT publisher_id FROM superhero WHERE superhero_name = 'A-Bomb'
)
AND race_id IS NULL;

