    AND atom2 IN (
        SELECT id FROM atom WHERE molecule_id = (
            SELECT molecule_id FROM atom WHERE element_symbol = 'Y'
        ) AND element_symbol = 'H'
    )
) OR (atom2 IN (
    SELECT id FROM atom WHERE molecule_id = (
        SELECT molecule_id FROM atom WHERE element_symbol = 'Y'
    )
    )
    AND atom1 IN (
        SELECT id FROM atom WHERE molecule_id = (
            SELECT molecule_id FROM atom WHERE element_symbol = 'Y'
        ) AND element_symbol = 'H'
    )
);

