SELECT COUNT(*) AS hydrogen_bond_count
FROM bond
WHERE molecule_id = (
    SELECT molecule_id FROM atom WHERE element = 'Y'
)
AND (
    molecule_id IN (
        SELECT molecule_id FROM atom WHERE element = 'H'
    )
